// Decide qué se puede enviar y qué no, y por qué. El "por qué" acaba en el campo
// `error` de la fila, en cristiano: quien escribe el mensaje es un gestor, no
// alguien que vaya a leer un log.
const cfg = $('Config (editar por tenant)').item.json;
const r = $json ?? {};
const code = r.statusCode ?? 0;
const body = (r.body ?? r) || {};
if (code >= 300 || (body && body.errors)) {
  throw new Error('Directus /items/conversation_messages ' + code + ': ' + JSON.stringify(body.errors || body));
}
const filas = Array.isArray(body.data) ? body.data : [];
const base_url = `https://graph.facebook.com/${cfg.graph_version || 'v21.0'}/${cfg.phone_number_id}/messages`;
const ahora = Date.now();

// Mismo dialecto que el adapter: el gestor escribe en una caja de texto normal y
// puede pegar markdown sin saberlo.
const aWhatsApp = (t) => (t || '').toString()
  .replace(/`{3}([\s\S]*?)`{3}/g, '$1')
  .replace(/^#{1,6}\s*(.+)$/gm, '*$1*')
  .replace(/\*\*\*(.+?)\*\*\*/g, '*$1*')
  .replace(/\*\*(.+?)\*\*/g, '*$1*')
  .replace(/__(.+?)__/g, '_$1_')
  .replace(/`(.+?)`/g, '$1')
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1: $2')
  .replace(/^[ \t]*[*+][ \t]+/gm, '- ')
  .trim();

const salida = [];
for (const f of filas) {
  const ses = f.session_id || {};
  const key = (ses.session_key || '').toString();
  const texto = aWhatsApp(f.texto);
  const comun = { _id: f.id, _enviar: false, _error: null, directus_base_url: cfg.directus_base_url };

  if (!texto) {
    salida.push({ json: { ...comun, _error: 'El mensaje está vacío.' } });
    continue;
  }
  // El canal de verdad lo dice el `session_key` de la sesión, NO la columna
  // `canal` de la fila: cuando el gestor escribe un mensaje desde Directus esa
  // columna se queda vacía (depende de la sesión y no puede tener un default),
  // y exigirla rechazaría precisamente el caso para el que está hecho esto.
  const canal = key.startsWith('whatsapp:') ? 'whatsapp' : (f.canal || 'desconocido');
  // Hoy solo se sabe enviar por WhatsApp. En webchat no hay a dónde empujar un
  // mensaje si el cliente cerró la pestaña, así que se falla claro en vez de
  // dejar la fila en 'pendiente' para siempre esperando algo que no va a pasar.
  if (canal !== 'whatsapp') {
    salida.push({ json: { ...comun,
      _error: `El canal "${canal}" no admite enviar un mensaje más tarde. Solo WhatsApp.` } });
    continue;
  }
  // La ventana de 24h de Meta vale también para la persona que escribe: pasada,
  // solo entra una plantilla aprobada. Sin esta comprobación el envío falla en
  // Graph con un error que no dice nada y el gestor no entiende por qué.
  const hasta = ses.ventana_hasta ? Date.parse(ses.ventana_hasta) : NaN;
  if (!Number.isFinite(hasta) || hasta <= ahora) {
    salida.push({ json: { ...comun,
      _error: 'La ventana de 24h de WhatsApp está cerrada: el cliente no escribe desde hace más de un día. '
            + 'Hasta que vuelva a escribir, solo se le puede mandar una plantilla aprobada por Meta.' } });
    continue;
  }

  salida.push({ json: { ...comun,
    _enviar: true,
    _url: base_url,
    _body: {
      messaging_product: 'whatsapp', recipient_type: 'individual',
      to: key.replace(/^whatsapp:/, ''),
      type: 'text', text: { preview_url: false, body: texto },
    },
  } });
}
return salida;

// Traduce la respuesta de Graph a la fila. Un envío que falla NO se reintenta
// solo: se deja 'fallido' con el motivo y lo decide una persona. Reintentar a
// ciegas contra WhatsApp es la forma de mandar cuatro veces lo mismo.
const p = $('Code · Preparar envíos').item.json;
const r = $json ?? {};
const code = r.statusCode ?? 0;
const body = (r.body ?? r) || {};
if (code >= 200 && code < 300 && body && Array.isArray(body.messages) && body.messages[0]) {
  return [{ json: { _id: p._id, directus_base_url: p.directus_base_url,
    _patch: { estado_envio: 'enviado', canal: 'whatsapp',
              canal_message_id: body.messages[0].id || null, error: null } } }];
}
const detalle = (body && body.error && body.error.message)
  ? body.error.message
  : JSON.stringify(body).slice(0, 400);
return [{ json: { _id: p._id, directus_base_url: p.directus_base_url,
  _patch: { estado_envio: 'fallido', error: `WhatsApp rechazó el envío (${code}): ${detalle}` } } }];

// No se ha llamado a WhatsApp: el motivo ya venía decidido.
const p = $json ?? {};
return [{ json: { _id: p._id, directus_base_url: p.directus_base_url,
  _patch: { estado_envio: 'fallido', error: p._error || 'No se pudo enviar.' } } }];
